select case when rating >= 3.9 then 'high' when rating >= 2.0 then 'mid' else 'low' end as rating_bucket, sum(rating) as total_rating, round(stddev(rating), 2) as stddev_rating, sum(case when city = 'London' then rating else 0 end) as london_rating from suppliers where rating < 3.8 group by case when rating >= 3.9 then 'high' when rating >= 2.0 then 'mid' else 'low' end order by total_rating desc, stddev_rating
